{'html': ''} [{"title": "Support Tab - CSSD-F2000GBMP600COR", "type": "support", "visible": true, "description": " ", "meta": {"contentType": "pdpTab"}}, {"title": "Downloads Tab - CSSD-F2000GBMP600COR", "type": "downloads", "visible": true, "description": " ", "content": [{"identifier": "Downloads Block - CSSD-F2000GBMP600COR", "title": "Downloads Block - CSSD-F2000GBMP600COR", "drivers": [], "documentations": [{"title": "CORSAIR M.2 SSD Quick Start Guide", "documentId": "CORSAIR M.2 SSD Quick Start Guide", "documentTitle": "CORSAIR M.2 SSD Quick Start Guide", "link": "https://assets.corsair.com/image/upload/corsairmedia/sys_master/productcontent/WW_UNIVERSAL_M.2_SSD_QSG_AA.pdf", "version": "1.0.0", "assetStatus": true, "isVisibleOnDownloadPage": false, "plataform": "All", "meta": {"contentType": "downloadDocumentation"}}, {"title": "Declaration of Conformity (DoC) document - CE-000386", "documentId": "Declaration of Conformity (DoC) document - CE-000386", "documentTitle": "Declaration of Conformity (DoC) document - CE-000386", "link": "https://assets.corsair.com/image/upload/v1786597275/downloads-prod/CE-000386.pdf", "version": "1.0.0", "assetStatus": true, "isVisibleOnDownloadPage": false, "skus": ["CSSD-F500GBMP600", "CSSD-F500GBMP600-RF2", "CSSD-F1000GBMP600", "CSSD-F1000GBMP600-RF2", "CSSD-F2000GBMP600", "CSSD-F2000GBMP600-RF2", "CSSD-F1000GBMP600R2", "CSSD-F2000GBMP600R2"], "plataform": "All", "meta": {"contentType": "downloadDocumentation"}}, {"title": "UKCA Declaration of Conformity (DoC) document - UKCA-000174", "documentId": "UKCA Declaration of Conformity (DoC) document - UKCA-000174", "documentTitle": "UKCA Declaration of Conformity (DoC) document - UKCA-000174", "link": "https://assets.corsair.com/image/upload/v1786603020/downloads-prod/UKCA-000174.pdf", "version": "1.0.0", "assetStatus": true, "isVisibleOnDownloadPage": false, "skus": ["CSSD-F500GBMP600", "CSSD-F500GBMP600-RF2", "CSSD-F1000GBMP600", "CSSD-F1000GBMP600-RF2", "CSSD-F2000GBMP600", "CSSD-F2000GBMP600-RF2", "CSSD-F1000GBMP600R2", "CSSD-F2000GBMP600R2"], "plataform": "All", "meta": {"contentType": "downloadDocumentation"}}], "meta": {"contentType": "download"}}], "meta": {"contentType": "pdpTab"}}, {"title": "Overview Tab | CSSD-F2000GBMP600COR", "type": "overview", "visible": true, "description": " ", "content": [{"title": "CSSD-F2000GBMP600COR - HTML Markup", "markup": "<link rel="stylesheet" type="text/css" href="//assets.ctfassets.net/87bewhkgljl1/2VB0ce22gqHZIgrBzZhGVK/481292d177d0154afebb0b2e4531197a/pdp-mp600.min.css"> <div id="pdp"> <section id="pdp-panel-hero" class="panel-template product-hero"> <video autoplay="" preload="" loop="" muted="" poster="//assets.corsair.com/image/upload/akamai/pdp/mp600-core/mp600_core_still.PNG" id="videoHero" style="display: inline-block;"> <source src="//assets.corsair.com/video/upload/akamai/pdp/mp600-core/MP600Core_Headerloop_v01.mp4"> </video> <div class="hero-content-container"> <div class="wrapper text-center white" style="position:relative;z-index:1"> <h2 class="h1 bebas">MP600 CORE</h2> <p>M.2 NVMe PCIe Gen 4 SSD</p> <a class="cta popup-youtube" href="https://www.youtube.com/watch?v=T4i6euuY1wI"><span>WATCH VIDEO</span></a> </div> </div> </section> <section class="panel-template fivepadding" style="background:#eee url('//assets.corsair.com/image/upload/akamai/pdp/mp600-core/mp600_core_1.png') center no-repeat; background-size:cover;"> <div class="wrapper"> <div class="col-half white top"> <h2 class="h1 bebas" style="color:#e6e900">EXTREME GEN4 STORAGE PERFORMANCE</h2> <p>A PCIe Gen4 x4 controller delivers up to 4,950MB/sec sequential read and 3,950MB/sec sequential write speeds, for blazing fast read, write, and response times.*</p> <p><em>* Performance and endurance vary by capacity.</em></p> </div> </div> </section> <section class="panel-template fivepadding" style="background:#fff url('//assets.corsair.com/image/upload/akamai/pdp/mp600-core/mp600_core_2.png') center no-repeat; background-size:cover;"> <div class="wrapper"> <div class="col-half offset-half white"> <h2 class="h1 bebas" style="color:#e6e900">High-speed Gen4 PCIe x4 NVMe M.2 Interface</h2> <p>Using PCIe Gen4 technology for maximum bandwidth, the MP600 CORE delivers incredible storage performance.</p> </div> </div> </section> <section class="panel-template fivepadding" style="background:#eee url('//assets.corsair.com/image/upload/akamai/_ui/responsive/common/images/bg-black-left.png') center no-repeat; background-size:cover;"> <div class="wrapper"> <div class="col-half white"> <h2 class="h1 bebas" style="color:#e6e900">Built-in Aluminum Heatspreader</h2> <p>Helps disperse heat and reduce throttling, so your SSD maintains sustained high performance.</p> </div> <div class="col-half bottom text-center"> <img loading="lazy" src="//assets.corsair.com/image/upload/akamai/pdp/mp600-core/mp600_core_heat.png" class="img-responsive"> </div> </div> </section> <section class="panel-template fivepadding" style="background:#fff url('//assets.corsair.com/image/upload/akamai/_ui/responsive/common/images/bg-dark-right.png') center no-repeat; background-size:cover;"> <div class="wrapper"> <div class="col-half bottom text-center"> <img loading="lazy" src="//assets.corsair.com/image/upload/akamai/pdp/mp400/images/mp400_qlc_density.jpg" class="img-responsive"> </div> <div class="col-half white"> <h2 class="h1 bebas" style="color:#e6e900">High-Density 3D QLC NAND</h2> <p>Offers even better value than previous generation TLC NAND, storing more data in the same amount of physical space.</p> </div> </div> </section> <section class="panel-template fivepadding" style="background:#eee url('//assets.corsair.com/image/upload/akamai/_ui/responsive/common/images/bg-black-left.png') center right no-repeat; background-size:cover;"> <div class="wrapper"> <div class="col-half white"> <h2 class="h1 bebas" style="color:#e6e900">Strong Endurance</h2> <p>The MP600 CORE reliably stores your data through years of use with endurance up to 1