<div id="pdp" class="hx1500i">

 <section id="panel-hero" class="panel-template product-hero">
 <div class="gradient-bg"></div>
 <video autoplay preload loop muted poster="https://assets.corsair.com/image/upload/f_auto,q_auto/products/Storage/CSSD-F1000GBMP700/Content/Corsair-Mp700-PDP-Loop-bkg.png" id="videoHero">
